const SLIDERwrapper=document.getElementById('sliderWrapper');const slides=document.querySelectorAll('.slide');const dotsContainer=document.getElementById('dotsContainer');let currentIndex=0;const totalSlides=slides.length;slides.forEach((_,index)=>{const dot=document.createElement('div');dot.classList.add('dot');if(index===0)dot.classList.add('active');dot.addEventListener('click',()=> goToSlide(index));dotsContainer.appendChild(dot);});const dots=document.querySelectorAll('.dot');function updateSlider(){SLIDERwrapper.style.transform=`translateX(-${currentIndex*100}%)`;dots.forEach((dot,index)=>{dot.classList.toggle('active',index===currentIndex);});}function goToSlide(index){currentIndex=index;updateSlider();}function nextSlide(){currentIndex=(currentIndex+1)% totalSlides;updateSlider();}function prevSlide(){currentIndex=(currentIndex-1+totalSlides)% totalSlides;updateSlider();}document.addEventListener('DOMContentLoaded',()=>{const SLIDERprevBtn=document.getElementById('prevBtn');const SLIDERnextBtn=document.getElementById('nextBtn');SLIDERnextBtn.addEventListener('click',nextSlide);SLIDERprevBtn.addEventListener('click',prevSlide);});let autoPlay=setInterval(nextSlide,4000);const SILDERcontainer=document.querySelector('.slider-container');SILDERcontainer.addEventListener('mouseenter',()=> clearInterval(autoPlay));SILDERcontainer.addEventListener('mouseleave',()=>{autoPlay=setInterval(nextSlide,4000);});